import { prisma } from '../../lib/prisma.js';
import { NotFoundError } from '../../lib/errors.js';
import type { CreateConversationBody } from './conversations.schema.js';

export async function listByProject(projectId: string) {
  return prisma.conversation.findMany({
    where: { projectId },
    orderBy: { createdAt: 'desc' },
  });
}

export async function create(projectId: string, data: CreateConversationBody) {
  const project = await prisma.project.findUnique({ where: { id: projectId } });
  if (!project) throw new NotFoundError('Project');
  return prisma.conversation.create({ data: { ...data, projectId } });
}

import { prisma } from '../../lib/prisma.js';
import { NotFoundError } from '../../lib/errors.js';
import type { CreateRequirementBody, UpdateRequirementBody } from './requirements.schema.js';

export async function listByProject(projectId: string) {
  return prisma.requirement.findMany({ where: { projectId }, orderBy: { createdAt: 'desc' } });
}

export async function create(projectId: string, data: CreateRequirementBody) {
  const project = await prisma.project.findUnique({ where: { id: projectId } });
  if (!project) throw new NotFoundError('Project');
  return prisma.requirement.create({ data: { ...data, projectId } });
}

export async function update(projectId: string, id: string, data: UpdateRequirementBody) {
  const req = await prisma.requirement.findFirst({ where: { id, projectId } });
  if (!req) throw new NotFoundError('Requirement');
  return prisma.requirement.update({ where: { id }, data });
}

export async function remove(projectId: string, id: string) {
  const req = await prisma.requirement.findFirst({ where: { id, projectId } });
  if (!req) throw new NotFoundError('Requirement');
  await prisma.requirement.delete({ where: { id } });
  return { success: true };
}

import { prisma } from '../../lib/prisma.js';
import { NotFoundError } from '../../lib/errors.js';
import type { CreateMilestoneBody, UpdateMilestoneBody } from './milestones.schema.js';

export async function listByProject(projectId: string) {
  return prisma.milestone.findMany({ where: { projectId }, orderBy: { createdAt: 'desc' } });
}

export async function create(projectId: string, data: CreateMilestoneBody) {
  const project = await prisma.project.findUnique({ where: { id: projectId } });
  if (!project) throw new NotFoundError('Project');
  return prisma.milestone.create({
    data: {
      ...data,
      projectId,
      dueDate: data.dueDate ? new Date(data.dueDate) : null,
    },
  });
}

export async function update(projectId: string, id: string, data: UpdateMilestoneBody) {
  const ms = await prisma.milestone.findFirst({ where: { id, projectId } });
  if (!ms) throw new NotFoundError('Milestone');
  return prisma.milestone.update({
    where: { id },
    data: {
      ...data,
      dueDate: data.dueDate ? new Date(data.dueDate) : undefined,
    },
  });
}

export async function remove(projectId: string, id: string) {
  const ms = await prisma.milestone.findFirst({ where: { id, projectId } });
  if (!ms) throw new NotFoundError('Milestone');
  await prisma.milestone.delete({ where: { id } });
  return { success: true };
}

import { prisma } from '../../lib/prisma.js';
import { NotFoundError } from '../../lib/errors.js';
import type { CreateCollaboratorBody } from './collaborators.schema.js';

export async function listByProject(projectId: string) {
  return prisma.collaborator.findMany({ where: { projectId } });
}

export async function create(projectId: string, data: CreateCollaboratorBody) {
  const project = await prisma.project.findUnique({ where: { id: projectId } });
  if (!project) throw new NotFoundError('Project');
  return prisma.collaborator.create({ data: { ...data, projectId } });
}

export async function remove(projectId: string, id: string) {
  const collab = await prisma.collaborator.findFirst({ where: { id, projectId } });
  if (!collab) throw new NotFoundError('Collaborator');
  await prisma.collaborator.delete({ where: { id } });
  return { success: true };
}

import { prisma } from '../../lib/prisma.js';
import { NotFoundError } from '../../lib/errors.js';
import type { CreatePlanBody, UpdatePlanBody } from './plans.schema.js';

export async function listByProject(projectId: string) {
  return prisma.projectPlan.findMany({ where: { projectId }, orderBy: { createdAt: 'desc' } });
}

export async function create(projectId: string, data: CreatePlanBody) {
  const project = await prisma.project.findUnique({ where: { id: projectId } });
  if (!project) throw new NotFoundError('Project');
  // Auto-increment version
  const last = await prisma.projectPlan.findFirst({
    where: { projectId },
    orderBy: { version: 'desc' },
  });
  return prisma.projectPlan.create({
    data: { ...data, projectId, version: (last?.version ?? 0) + 1 },
  });
}

export async function update(projectId: string, id: string, data: UpdatePlanBody) {
  const plan = await prisma.projectPlan.findFirst({ where: { id, projectId } });
  if (!plan) throw new NotFoundError('Plan');
  return prisma.projectPlan.update({
    where: { id },
    data: { ...data, version: plan.version + 1 },
  });
}

export async function remove(projectId: string, id: string) {
  const plan = await prisma.projectPlan.findFirst({ where: { id, projectId } });
  if (!plan) throw new NotFoundError('Plan');
  await prisma.projectPlan.delete({ where: { id } });
  return { success: true };
}

import { z } from 'zod/v4';

export const CreateMilestoneBody = z.object({
  title: z.string().min(1),
  description: z.string().optional().nullable(),
  dueDate: z.string().datetime().optional().nullable(),
  status: z.enum(['pending', 'in-progress', 'completed', 'cancelled']).default('pending'),
});

export const UpdateMilestoneBody = CreateMilestoneBody.partial();

export type CreateMilestoneBody = z.infer<typeof CreateMilestoneBody>;
export type UpdateMilestoneBody = z.infer<typeof UpdateMilestoneBody>;

import { z } from 'zod/v4';

export const CreateRequirementBody = z.object({
  title: z.string().min(1),
  description: z.string().optional().nullable(),
  category: z.enum(['need', 'goal', 'requirement']).default('requirement'),
  status: z.enum(['open', 'in-progress', 'met', 'cancelled']).default('open'),
  priority: z.enum(['low', 'medium', 'high', 'critical']).default('medium'),
