function templateCallback(handler: (uri: URL) => ReturnType<ReadResourceTemplateCallback>): ReadResourceTemplateCallback {
  return handler;
}

function extractId(uri: URL): string {
  const parts = uri.pathname.split("/");
  return parts[parts.length - 1] ?? "";
}

export function registerResources(server: McpServer) {
  server.resource(
    "person",
    "people://{id}",
    templateCallback(async (uri) => {
      const id = extractId(uri);
      const person = await peopleService.getById(id);
      return {
        contents: [{
          uri: uri.href,
          text: JSON.stringify(person, null, 2),
          mimeType: "application/json" as const,
        }],
      };
    }),
  );

  server.resource(
    "project",
    "project://{id}",
    templateCallback(async (uri) => {
      const id = extractId(uri);
      const project = await projectsService.getById(id);
      return {
        contents: [{
          uri: uri.href,
          text: JSON.stringify(project, null, 2),
          mimeType: "application/json" as const,
        }],
      };
    }),
  );

  server.resource(
    "dashboard",
    "dashboard://summary",
    templateCallback(async (uri) => {
      const dashboard = await dashboardService.getDashboard();
      return {
        contents: [{
          uri: uri.href,
          text: JSON.stringify(dashboard, null, 2),
          mimeType: "application/json" as const,
        }],
      };
    }),
  );
}

