/**
 * Ensoria OS MCP Client — Test Script
 *
 * Connects to the MCP server, discovers tools, calls several of them,
 * and prints results.
 *
 * Usage: npx tsx test-mcp.ts
 */
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";

const MCP_URL = "http://localhost:3000/api/mcp";
const API_URL = "http://localhost:3000/api";
const CREDENTIALS = { email: "admin@ensoria.dev", password: "test123" };

// ── Auth: get a JWT token ──────────────────────────
async function getToken(): Promise<string> {
  const res = await fetch(`${API_URL}/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(CREDENTIALS),
  });
  const json = await res.json() as { data: { token: string } };
  return json.data.token;
}

// ── Helper: format any value for display ────────────
function fmt(val: unknown): string {
  if (val === null || val === undefined) return "—";
  if (typeof val === "string") return val.length > 60 ? val.slice(0, 60) + "…" : val;
  if (typeof val === "number") return val.toLocaleString();
  if (Array.isArray(val)) return `[${val.length} items]`;
  return JSON.stringify(val).slice(0, 60);
}

function hr(label: string) {
  console.log(`\n${"─".repeat(50)}`);
  console.log(`  ${label}`);
  console.log(`${"─".repeat(50)}`);
}

function ok(msg: string) {
  console.log(`  ✅ ${msg}`);
}

function info(msg: string) {
  console.log(`     ${msg}`);
}

// ── Main ────────────────────────────────────────────
async function main() {
  console.log("\n🧠  Ensoria OS — MCP Client Test\n");

  // 1. Get JWT token
  console.log("🔑  Authenticating…");
  const token = await getToken();
  ok(`JWT token obtained (${token.slice(0, 20)}…)`);

  // 2. Create MCP client
  console.log("\n🔌  Connecting to MCP server…");
  const transport = new StreamableHTTPClientTransport(new URL(MCP_URL), {
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
      Authorization: `Bearer ${token}`,
    },
  });

  const client = new Client(
    { name: "ensoria-test-client", version: "1.0.0" },
    { capabilities: {} },
  );

  await client.connect(transport);
  ok("MCP session initialized");

  // 3. List tools
  hr("tools/list");
  const { tools } = await client.listTools();
  info(`Found ${tools.length} tools:`);
  const byNamespace = new Map<string, number>();
  for (const t of tools) {
    const ns = t.name.split("_").slice(0, -1).join("_") || t.name;
    byNamespace.set(ns, (byNamespace.get(ns) || 0) + 1);
    info(`  • ${t.name} — ${(t.description ?? "").slice(0, 55)}`);
  }
  console.log();
  for (const [ns, count] of byNamespace) {
    info(`${ns}: ${count} tools`);
  }

  // 4. Call: list_people
  hr('tools/call — "list_people"');
  const peopleResult = await client.callTool({ name: "list_people", arguments: {} });
  const peopleText = peopleResult.content
    .filter((c) => c.type === "text")
    .map((c) => JSON.parse(c.text))
    .flat();
  info(`Found ${peopleText.length} people:`);
  for (const p of peopleText) {
    info(`  • ${p.name.padEnd(20)} ${p.type.padEnd(12)} stage: ${p.stage}`);
  }

  // 5. Call: get_dashboard
  hr('tools/call — "get_dashboard"');
  const dashResult = await client.callTool({ name: "get_dashboard", arguments: {} });
  const dashText = dashResult.content
    .filter((c) => c.type === "text")
    .map((c) => JSON.parse(c.text));
  const d = dashText[0]?.metrics ?? {};
  info(`People:        ${d.totalPeople}`);
  info(`Projects:      ${d.totalProjects}`);
  info(`Pipeline:      €${(d.pipelineValue ?? 0).toLocaleString()}`);
  info(`Win rate:      ${Math.round((d.winRate ?? 0) * 100)}%`);
  info(`Avg deal size: €${(d.avgDealSize ?? 0).toLocaleString()}`);

  // 6. If we have a person, try creating a project via MCP
  if (peopleText.length > 0) {
    const firstPerson = peopleText[0];
    hr(`tools/call — "create_project" (for ${firstPerson.name})`);
    const projectResult = await client.callTool({
      name: "create_project",
      arguments: {
        name: "MCP Test Project",
        peopleId: firstPerson.id,
        value: 25000,
        stage: "Opportunity",
        description: "Created via MCP test script",
      },
    });
    const projText = projectResult.content
      .filter((c) => c.type === "text")
      .map((c) => JSON.parse(c.text));
    const proj = projText[0] ?? {};
    ok(`Project "${proj.name}" created (id: ${(proj.id ?? "").slice(0, 12)}…)`);
    info(`Stage: ${proj.stage}  |  Value: €${fmt(proj.value)}`);

    // 7. Move project stage via MCP
    hr(`tools/call — "move_project_stage" → Implementation`);
    const moveResult = await client.callTool({
      name: "move_project_stage",
      arguments: { id: proj.id, stage: "Implementation" },
    });
    const movedText = moveResult.content
      .filter((c) => c.type === "text")
      .map((c) => JSON.parse(c.text));
    info(`Project stage: ${movedText[0]?.stage ?? "?"}`);

    // 8. Get the project via resource
    hr(`resources/read — "project://${(proj.id ?? "").slice(0, 12)}…"`);
    try {
      const resourceResult = await client.readResource({ uri: `project://${proj.id}` });
      const resContent = resourceResult.contents[0];
      if (resContent && "text" in resContent) {
        const projData = JSON.parse(resContent.text);
        info(`Name:    ${projData.name}`);
        info(`Stage:   ${projData.stage}`);
        info(`Value:   €${fmt(projData.value)}`);
        info(`Tabs:    conversations(${projData.conversations?.length ?? 0}), ` +
              `requirements(${projData.requirements?.length ?? 0}), ` +
              `milestones(${projData.milestones?.length ?? 0})`);
      }
    } catch (e) {
      info(`Resource read (expected for non-template URIs): ${(e as Error).message}`);
    }
  }

  // 9. Cleanup
  hr("Session");
  await client.close();
  ok("MCP session closed");

  console.log(`\n${"═".repeat(50)}`);
  console.log("  🎉 All MCP tests passed!");
  console.log(`${"═".repeat(50)}\n`);
}

main().catch((err) => {
  console.error("\n❌  Test failed:", err);
  process.exit(1);
});

