import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import type { ResourceTemplate, ResourceMetadata } from "@modelcontextprotocol/sdk/types.js";
import * as peopleService from "../people/people.service.js";
import * as projectsService from "../projects/projects.service.js";
import * as dashboardService from "../dashboard/dashboard.service.js";

const JSON_MIME = "application/json" as const;

export function registerResources(server: McpServer) {
  const personTemplate: ResourceTemplate = {
    uriTemplate: "people://{id}",
    description: "A person/contact in the CRM, including their projects",
    mimeType: JSON_MIME,
  };

  const projectTemplate: ResourceTemplate = {
    uriTemplate: "project://{id}",
    description: "A project with all nested resources (conversations, requirements, milestones, etc.)",
    mimeType: JSON_MIME,
  };

  const dashboardTemplate: ResourceTemplate = {
    uriTemplate: "dashboard://summary",
    description: "CRM dashboard with aggregate metrics, stage distribution, and recent activity",
    mimeType: JSON_MIME,
  };

  const metadata: ResourceMetadata = {};

  server.resource(
    "person",
    personTemplate,
    metadata,
    async (uri, variables) => {
      const id = variables["id"] as string;
      const person = await peopleService.getById(id);
      return {
        contents: [{
          uri: uri.href,
          text: JSON.stringify(person, null, 2),
          mimeType: JSON_MIME,
        }],
      };
    },
  );

  server.resource(
    "project",
    projectTemplate,
    metadata,
    async (uri, variables) => {
      const id = variables["id"] as string;
      const project = await projectsService.getById(id);
      return {
        contents: [{
          uri: uri.href,
          text: JSON.stringify(project, null, 2),
          mimeType: JSON_MIME,
        }],
      };
    },
  );

  server.resource(
    "dashboard",
    dashboardTemplate,
    metadata,
    async (uri) => {
      const dashboard = await dashboardService.getDashboard();
      return {
        contents: [{
          uri: uri.href,
          text: JSON.stringify(dashboard, null, 2),
          mimeType: JSON_MIME,
        }],
      };
    },
  );
}

import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import * as peopleService from "../people/people.service.js";
import * as projectsService from "../projects/projects.service.js";
import * as dashboardService from "../dashboard/dashboard.service.js";

/**
 * Resource URI handlers — called from the custom ReadResourceRequest handler
 * in the MCP plugin when the client requests a resource by URI.
 */
export interface ResourceHandlers {
  [pattern: string]: (uri: URL) => Promise<{
    uri: string;
    text: string;
    mimeType: string;
  }>;
}

export function getResourceHandlers(): ResourceHandlers {
  return {
    "people://": async (uri) => {
      const id = uri.pathname.split("/").pop() ?? "";
      const person = await peopleService.getById(id);
      return { uri: uri.href, text: JSON.stringify(person, null, 2), mimeType: "application/json" };
    },
    "project://": async (uri) => {
      const id = uri.pathname.split("/").pop() ?? "";
      const project = await projectsService.getById(id);
      return { uri: uri.href, text: JSON.stringify(project, null, 2), mimeType: "application/json" };
    },
    "dashboard://": async (uri) => {
      const dashboard = await dashboardService.getDashboard();
      return { uri: uri.href, text: JSON.stringify(dashboard, null, 2), mimeType: "application/json" };
    },
  };
}

/**
 * Resource template definitions for the capabilities list.
 * These are returned when the client calls resources/templates/list.
 */
export function getResourceTemplateDefinitions() {
  return [
    {
      uriTemplate: "people://{id}",
      name: "person",
      description: "A person/contact in the CRM, including their projects",
      mimeType: "application/json",
    },
    {
      uriTemplate: "project://{id}",
      name: "project",
      description: "A project with all nested resources",
      mimeType: "application/json",
    },
    {
      uriTemplate: "dashboard://summary",
      name: "dashboard",
      description: "CRM dashboard with aggregate metrics, stage distribution, and recent activity",
      mimeType: "application/json",
    },
  ];
}

