import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import type { ResourceTemplate, ResourceMetadata } from "@modelcontextprotocol/sdk/types.js";
import * as peopleService from "../people/people.service.js";
import * as projectsService from "../projects/projects.service.js";
import * as dashboardService from "../dashboard/dashboard.service.js";

const JSON_MIME = "application/json" as const;

/**
 * Create a plain resource template object.
 * At runtime, `registerResource` only checks `typeof !== "string"`,
 * so a plain `{ uriTemplate }` object works fine despite the complex SDK type.
 */
function template(uriTemplate: string, description?: string): ResourceTemplate {
  return { uriTemplate, description, mimeType: JSON_MIME } as unknown as ResourceTemplate;
}

export function registerResources(server: McpServer) {
  const metadata: ResourceMetadata = {};

  server.registerResource(
    "person",
    template("people://{id}", "A person/contact in the CRM, including their projects"),
    metadata,
    async (uri, variables) => {
      const id = variables["id"] as string;
      const person = await peopleService.getById(id);
      return {
        contents: [{ uri: uri.href, text: JSON.stringify(person, null, 2), mimeType: JSON_MIME }],
      };
    },
  );

  server.registerResource(
    "project",
    template("project://{id}", "A project with all nested resources"),
    metadata,
    async (uri, variables) => {
      const id = variables["id"] as string;
      const project = await projectsService.getById(id);
      return {
        contents: [{ uri: uri.href, text: JSON.stringify(project, null, 2), mimeType: JSON_MIME }],
      };
    },
  );

  server.registerResource(
    "dashboard",
    template("dashboard://summary", "CRM dashboard with aggregate metrics and recent activity"),
    metadata,
    async (uri) => {
      const dashboard = await dashboardService.getDashboard();
      return {
        contents: [{ uri: uri.href, text: JSON.stringify(dashboard, null, 2), mimeType: JSON_MIME }],
      };
    },
  );
}

