/**
 * Ensoria MCP — Full Diagnostic Test
 *
 * Tests ALL 24 MCP tools + 3 resources.
 * Shows RAW and FORMATTED output for each.
 */
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";

const MCP_URL = "http://localhost:3000/api/mcp";
const API_URL = "http://localhost:3000/api";

let token: string;
let sessionId: string | undefined;
let testPersonId: string;
let testProjectId: string;
let testConvId: string;
let testReqId: string;
let testMsId: string;
let testCollabId: string;
let testPlanId: string;

// ── Helpers ──────────────────────────────────────────
async function api(method: string, path: string, body?: unknown) {
  const opts: RequestInit = {
    method,
    headers: { "Content-Type": "application/json" },
  };
  if (token) (opts.headers as Record<string, string>)["Authorization"] = `Bearer ${token}`;
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(`${API_URL}${path}`, opts);
  return res.json();
}

async function mcpCall(method: string, params?: Record<string, unknown>, id = 1) {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    Authorization: `Bearer ${token}`,
  };
  if (sessionId) headers["mcp-session-id"] = sessionId;

  const res = await fetch(MCP_URL, {
    method: "POST",
    headers,
    body: JSON.stringify({ jsonrpc: "2.0", id, method, params }),
  });

  const text = await res.text();

  // Extract original session ID from headers
  const sid = res.headers.get("mcp-session-id");
  if (sid && !sessionId) sessionId = sid;

  return { raw: text, parsed: parseSSEorJSON(text) };
}

function parseSSEorJSON(text: string): unknown {
  // SSE format: "event: message\ndata: {...}"
  const dataLine = text.split("\n").find((l) => l.startsWith("data: "));
  if (dataLine) {
    try {
      return JSON.parse(dataLine.slice(6));
    } catch { /* fallthrough */ }
  }
  // Plain JSON
  try {
    return JSON.parse(text);
  } catch {
    return { _parseError: "Could not parse", text: text.slice(0, 200) };
  }
}

function fmt(val: unknown, indent = 2): string {
  return JSON.stringify(val, null, indent);
}

function section(title: string) {
  const line = "─".repeat(60);
  console.log(`\n${line}`);
  console.log(`  ${title}`);
  console.log(line);
}

function toolResult(parsed: unknown): string {
  const p = parsed as Record<string, unknown>;
  const result = p?.result as Record<string, unknown> | undefined;
  if (!result) return `  ⚠️  Error: ${fmt(p?.error ?? p)}`;
  const content = result.content as Array<{ type: string; text: string }> | undefined;
  if (!content || content.length === 0) return "  (no content)";
  return content
    .filter((c) => c.type === "text")
    .map((c) => c.text.slice(0, 500))
    .join("\n");
}

async function call(label: string, method: string, params: Record<string, unknown> = {}) {
  const { raw, parsed } = await mcpCall(method, params);
  section(label);
  console.log("  📡 RAW:");
  console.log(raw.slice(0, 400));
  if (raw.length > 400) console.log(`    … (${raw.length} total chars)`);
  console.log("\n  📊 FORMATTED:");
  console.log(toolResult(parsed));
}

async function resource(label: string, uri: string) {
  const { raw, parsed } = await mcpCall("resources/read", { uri });
  section(label);
  console.log("  📡 RAW:");
  console.log(raw.slice(0, 400));
  if (raw.length > 400) console.log(`    … (${raw.length} total chars)`);
  console.log("\n  📊 FORMATTED:");
  const result = (parsed as Record<string, any>)?.result;
  const contents = result?.contents;
  if (contents) {
    for (const c of contents) {
      try {
        const data = JSON.parse(c.text);
        console.log(fmt(data).slice(0, 500));
      } catch {
        console.log(c.text.slice(0, 500));
      }
    }
  } else {
    console.log(fmt(parsed).slice(0, 500));
  }
}

// ── Main ────────────────────────────────────────────
async function main() {
  console.log("\n🧠  Ensoria OS — MCP Full Diagnostic (24 tools + 3 resources)\n");

  // 0. Auth
  console.log("🔑  Authenticating…");
  const login = await api("POST", "/auth/login", {
    email: "admin@ensoria.dev",
    password: "test123",
  });
  token = (login as any).data?.token;
  if (!token) { console.error("Auth failed"); process.exit(1); }
  console.log(`  Token: ${token.slice(0, 20)}…\n`);

  // 1. Initialize MCP session
  console.log("🔌  Initializing MCP session…");
  const initResult = await mcpCall("initialize", {
    protocolVersion: "2025-03-26",
    capabilities: {},
    clientInfo: { name: "diagnostic", version: "1.0" },
  });
  console.log(`  Session ID: ${sessionId}\n`);

  // ── Create test data ────────────────────────────────
  section("SEED DATA — Create person + project for testing");

  const personRaw = await api("POST", "/people", {
    name: "Test Persona MCP",
    type: "client",
    email: "test@mcp.ensoria",
    stage: "Contact",
  });
  testPersonId = (personRaw as any).data?.id;
  console.log(`  Person created: ${testPersonId}`);

  const projRaw = await api("POST", "/projects", {
    name: "Progetto Test MCP Completo",
    peopleId: testPersonId,
    value: 15000,
    stage: "Opportunity",
    description: "Progetto per test diagnostico MCP",
  });
  testProjectId = (projRaw as any).data?.id;
  console.log(`  Project created: ${testProjectId}`);

  // ── ── ── ── ── ── ── ── ── ── ── ── ── ── ── ──
  // TOOLS
  // ── ── ── ── ── ── ── ── ── ── ── ── ── ── ── ──

  // ── PEOPLE ──
  await call("TOOL 1/24 — list_people", "tools/call", {
    name: "list_people", arguments: {},
  });

  await call("TOOL 2/24 — get_person", "tools/call", {
    name: "get_person", arguments: { id: testPersonId },
  });

  await call("TOOL 3/24 — create_person", "tools/call", {
    name: "create_person", arguments: {
      name: "Persona MCP Temporanea",
      type: "partner",
      email: "temp@mcp.ensoria",
      stage: "Opportunity",
    },
  });

  // Grab that temp ID for later deletion
  const listAfterCreate = await api("GET", "/people");
  const tempPersonId = ((listAfterCreate as any).data as Array<{ id: string }>)
    .find((p) => p.id !== testPersonId)?.id;

  await call("TOOL 4/24 — update_person", "tools/call", {
    name: "update_person", arguments: {
      id: tempPersonId,
      company: "MCP Corp",
      notes: "Aggiornato via MCP",
    },
  });

  await call("TOOL 5/24 — change_person_stage", "tools/call", {
    name: "change_person_stage", arguments: {
      id: tempPersonId,
      stage: "Client",
    },
  });

  await call("TOOL 6/24 — delete_person", "tools/call", {
    name: "delete_person", arguments: { id: tempPersonId },
  });

  // ── PROJECTS ──
  await call("TOOL 7/24 — list_projects", "tools/call", {
    name: "list_projects", arguments: {},
  });

  await call("TOOL 8/24 — get_project", "tools/call", {
    name: "get_project", arguments: { id: testProjectId },
  });

  await call("TOOL 9/24 — create_project", "tools/call", {
    name: "create_project", arguments: {
      name: "Progetto MCP Temp",
      peopleId: testPersonId,
      value: 5000,
      stage: "Contact",
    },
  });

  // Temp project ID for stage move + delete
  const projsAfterCreate = await api("GET", "/projects");
  const tempProjId = ((projsAfterCreate as any).data as Array<{ id: string }>)
    .find((p) => p.id !== testProjectId)?.id;

  await call("TOOL 10/24 — move_project_stage", "tools/call", {
    name: "move_project_stage", arguments: {
      id: tempProjId,
      stage: "Proposal",
    },
  });

  await call("TOOL 11/24 — delete_project", "tools/call", {
    name: "delete_project", arguments: { id: tempProjId },
  });

  // ── CONVERSATIONS ──
  await call("TOOL 12/24 — list_conversations", "tools/call", {
    name: "list_conversations", arguments: { projectId: testProjectId },
  });

  await call("TOOL 13/24 — add_conversation", "tools/call", {
    name: "add_conversation", arguments: {
      projectId: testProjectId,
      channel: "email",
      direction: "inbound",
      subject: "Primo contatto",
      content: "Ciao, vorrei sapere di più sui vostri servizi.",
    },
  });

  // ── REQUIREMENTS ──
  await call("TOOL 14/24 — list_requirements", "tools/call", {
    name: "list_requirements", arguments: { projectId: testProjectId },
  });

  await call("TOOL 15/24 — add_requirement", "tools/call", {
    name: "add_requirement", arguments: {
      projectId: testProjectId,
      title: "Autenticazione utenti",
      category: "requirement",
      priority: "high",
      description: "Sistema di login con JWT",
    },
  });

  // Grab requirement ID for later
  const reqs = await api("GET", `/projects/${testProjectId}/requirements`);
  testReqId = ((reqs as any).data?.[0]?.id);

  // ── MILESTONES ──
  await call("TOOL 16/24 — list_milestones", "tools/call", {
    name: "list_milestones", arguments: { projectId: testProjectId },
  });

  await call("TOOL 17/24 — add_milestone", "tools/call", {
    name: "add_milestone", arguments: {
      projectId: testProjectId,
      title: "MVP completato",
      description: "Prima versione funzionante",
    },
  });

  // Grab milestone ID
  const mss = await api("GET", `/projects/${testProjectId}/milestones`);
  testMsId = ((mss as any).data?.[0]?.id);

  await call("TOOL 18/24 — update_milestone", "tools/call", {
    name: "update_milestone", arguments: {
      projectId: testProjectId,
      id: testMsId,
      status: "completed",
    },
  });

  // ── COLLABORATORS ──
  await call("TOOL 19/24 — list_collaborators", "tools/call", {
    name: "list_collaborators", arguments: { projectId: testProjectId },
  });

  await call("TOOL 20/24 — add_collaborator", "tools/call", {
    name: "add_collaborator", arguments: {
      projectId: testProjectId,
      name: "Marco Verdi",
      role: "Developer",
      email: "marco@mcp.ensoria",
    },
  });

  // Grab collaborator ID
  const collabs = await api("GET", `/projects/${testProjectId}/collaborators`);
  testCollabId = ((collabs as any).data?.[0]?.id);

  await call("TOOL 21/24 — remove_collaborator", "tools/call", {
    name: "remove_collaborator", arguments: {
      projectId: testProjectId,
      id: testCollabId,
    },
  });

  // ── PLANS ──
  await call("TOOL 22/24 — list_plans", "tools/call", {
    name: "list_plans", arguments: { projectId: testProjectId },
  });

  await call("TOOL 23/24 — create_plan", "tools/call", {
    name: "create_plan", arguments: {
      projectId: testProjectId,
      title: "Piano di Sviluppo",
      content: "# Sprint 1\n- Setup progetto\n- Auth\n\n# Sprint 2\n- API CRUD\n- Frontend base",
    },
  });

  // ── DASHBOARD ──
  await call("TOOL 24/24 — get_dashboard", "tools/call", {
    name: "get_dashboard", arguments: {},
  });

  // ── ── ── ── ── ── ── ── ── ── ── ── ── ── ── ──
  // RESOURCES
  // ── ── ── ── ── ── ── ── ── ── ── ── ── ── ── ──

  // List templates
  section("RESOURCE — resources/templates/list");
  const tmpl = await mcpCall("resources/templates/list");
  console.log("  📡 RAW:");
  console.log(tmpl.raw.slice(0, 600));
  console.log("\n  📊 FORMATTED (templates):");
  const templates = ((tmpl.parsed as any)?.result?.resourceTemplates ?? []) as Array<{ name: string; uriTemplate: string }>;
  for (const t of templates) {
    console.log(`  • ${t.name}: ${t.uriTemplate}`);
  }

  await resource("RESOURCE — people://{id}", `people://${testPersonId}`);
  await resource("RESOURCE — project://{id}", `project://${testProjectId}`);
  await resource("RESOURCE — dashboard://summary", "dashboard://summary");

  // ── Cleanup test data ─────────────────────────────
  section("CLEANUP");
  await api("DELETE", `/projects/${testProjectId}`);
  await api("DELETE", `/people/${testPersonId}`);
  const finalPeople = await api("GET", "/people");
  const finalProjs = await api("GET", "/projects");
  const pCount = ((finalPeople as any).data ?? []).length;
  const prCount = ((finalProjs as any).data ?? []).length;
  console.log(`  People: ${pCount} (should be 0)`);
  console.log(`  Projects: ${prCount} (should be 0)`);

  // Close
  try {
    const client = new Client(
      { name: "diag", version: "1.0" },
      { capabilities: {} },
    );
    const tr = new StreamableHTTPClientTransport(new URL(MCP_URL), {
      requestInit: {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
          Accept: "application/json, text/event-stream",
        },
      },
    });
    await client.connect(tr);
    await client.close();
    console.log("  Session closed");
  } catch { /* ok */ }

  // ── Summary ─────────────────────────────────────
  console.log(`\n${"═".repeat(60)}`);
  console.log("  🎉 24 tools + 3 resources — ALL TESTED");
  console.log("  DB cleaned — no test data remains");
  console.log(`${"═".repeat(60)}\n`);
}

main().catch((err) => {
  console.error("\n❌  Fatal:", err);
  process.exit(1);
});

