            <span className="text-sm text-[#9898b0]">{project.people?.name || '—'}</span>
            {project.value != null && (
              <span className="text-sm font-medium text-green-400">€{project.value.toLocaleString()}</span>
            )}
          </div>
        </div>
        <Select
